class TxnCounter {
  Map<String,Integer> count = new HashMap<>();

  void record(String acct) {
    // merge: absent→put 1, present→old+1
    count.merge(acct, 1, Integer::sum);
  }
  void initIfNew(String acct) {
    count.putIfAbsent(acct, 0);   // no overwrite
  }
  // put() internals:
  //  idx = hash(k) & (cap-1)
  //  walk bucket: if hash== && key.equals()
  //     node.value = newVal; return oldVal  (key kept)
  //  else append new node; size++
  Integer set(String acct, int v){
    return count.put(acct, v);    // returns previous
  }
}
